const assert = require('node:assert/strict')
const fs = require('node:fs')
const ts = require('typescript')
require.extensions['.ts'] = (mod, filename) => {
  const source = fs.readFileSync(filename,'utf8')
  const js = ts.transpileModule(source, { compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2020}}).outputText
  mod._compile(js,filename)
}
const {nivelEfetivoAcao,podeExecutarAcao,permissaoDaRotaProducao}=require('../lib/producaoPermissoes.ts')
const config={acoes:{'producao.geral.consultar':'consulta','producao.geral.mover':'oculto','producao.geral.criar':'edicao'}}
assert.equal(nivelEfetivoAcao('funcionario',{producao:'oculto'},config,'producao','producao.geral.criar'),'oculto')
assert.equal(nivelEfetivoAcao('funcionario',{producao:'edicao'},config,'producao','producao.geral.mover'),'oculto')
assert.equal(nivelEfetivoAcao('funcionario',{producao:'consulta'},config,'producao','producao.geral.criar'),'consulta')
assert.equal(nivelEfetivoAcao('master',{},config,'producao','producao.geral.mover'),'edicao')
assert.equal(podeExecutarAcao('funcionario',{producao:'consulta'},config,'producao','producao.geral.consultar'),true)
assert.equal(podeExecutarAcao('funcionario',{producao:'consulta'},config,'producao','producao.geral.criar','edicao'),false)
assert.equal(podeExecutarAcao('funcionario',{producao:'edicao'},config,'producao','producao.geral.mover','edicao'),false)
assert.equal(podeExecutarAcao('funcionario',{producao:'edicao'},{acoes:{}},'producao','producao.geral.criar','edicao'),true)
assert.deepEqual(permissaoDaRotaProducao('/producao'),{setor:'producao',acao:'producao.geral.consultar'})
assert.deepEqual(permissaoDaRotaProducao('/producao/ordens'),{setor:'producao',acao:'producao.geral.consultar'})
assert.deepEqual(permissaoDaRotaProducao('/producao/plano-corte'),{setor:'producao',acao:'producao.plano_corte.consultar'})
assert.deepEqual(permissaoDaRotaProducao('/producao/medicao-final/abc'),{setor:'medida-final-msdwtt9y',acao:'producao.medida_final.consultar'})
assert.equal(permissaoDaRotaProducao('/clientes/1'),null)
const auth=fs.readFileSync(require.resolve('../components/AuthGate.tsx'),'utf8')
assert.match(auth,/<ProducaoRouteGuard>/)
const guard=fs.readFileSync(require.resolve('../components/system/ProducaoRouteGuard.tsx'),'utf8')
assert.match(guard,/setVerificacao/)
assert.match(guard,/verificacao.rota === pathname/)
const pg=fs.readFileSync(require.resolve('../app/producao/page.tsx'),'utf8')
for(const a of ['producao.geral.mover','producao.geral.editar','producao.geral.criar','producao.geral.etapas','producao.geral.liberar'])
 assert.match(pg,new RegExp("pode\\(['\\\"]"+a.replaceAll('.','\\.')+"['\\\"]\\)"))
const api=fs.readFileSync(require.resolve('../app/api/producao/kanban/movimentar/route.ts'),'utf8')
assert.match(api,/usuarioPodeAcaoServer/)
assert.match(api,/acaoId:'producao.geral.mover',minimo:'edicao'/)
assert.deepEqual(permissaoDaRotaProducao('/producao/separacao'),{setor:'producao',acao:'producao.separacao.consultar'})
const sep = fs.readFileSync(require.resolve('../app/api/producao/separacao/route.ts'),'utf8')
assert.match(sep,/usuarioPodeAcaoServer/)
assert.match(sep,/producao.separacao.editar/)
assert.match(sep,/producao.separacao.consultar/)
const desktop = fs.readFileSync(require.resolve('../components/Sidebar.tsx'),'utf8')
const mobile = fs.readFileSync(require.resolve('../components/system/MobileNavigationControls.tsx'),'utf8')
assert.match(desktop,/guiaLiberada/)
assert.match(desktop,/permissaoDaRotaProducao/)
assert.match(mobile,/permissaoDaRotaProducao/)
console.log('PASS: Produção: ocultação, leitura, edição por ação, Master, navegação, telas e Kanban API.')
